using DH.Grading.Core;

namespace DH.Grading.Civil;

/// <summary>옹벽 형태(스타일) — 절토부/성토부에 어떤 옹벽을 3D로 만들지(JACK 0721 로드맵).
/// 치수는 스타일별 코드 고정. 앞으로 콘크리트 옹벽 등 추가.</summary>
public enum WallStyle
{
    없음_사면,      // 옹벽 없음 — 사면(노리)만
    보강토,         // 보강토(블록) 옹벽 — 근수직(n≤0.05), 블록 격자 (기존)
    앵커판넬,       // 앵커판넬 옹벽 — 프리캐스트 패널 + 어스앵커(가운데 200×200 홈) + 자연석 무늬(정착구 주변 제외)
    역T형,          // [0730 — JACK 확정] RC 벽체+저판 — 계획경계에 붙고 1단 안에 끝나는 순수 옹벽에만 적용.
                    //   2단 이상 되는 구간은 자동 대체: 절토=앵커판넬, 성토=보강토(선택 시 팝업 안내).
    // (콘크리트 스타일은 0730 삭제 — 자연석 무늬는 앵커판넬로 이식)
}

/// <summary>
/// 정지 파라미터의 세션 보관소 — [설정] 명령으로 바꾸고 [정지면 생성]이 읽어간다.
/// 단순 정적 보관(도면 세션 동안 유지). 구배 표기는 1:n = 수직1:수평n.
/// </summary>
public static class GradingSettings
{
    /// <summary>플러그인 버전 — 팝업 첫 줄에 표시(새 빌드 설치 확인용). 커밋마다 갱신.</summary>
    public const string Version = "v19.0 (2026-08-05 — **옹벽 재설계: 옹벽선 정본화 + 띠 분할**(JACK: '단독으로 돌리든 이어서하든 둘 다 만족할 새로운 접근이 필요하다. 땜질식으로 하면 다른 경우의 수에 계속 막힌다. 지표면은 잘 만들어지는데 옹벽객체와 SHP 생성이 문제다'). **원인**: 내보내기가 지표면을 보고 만드는 게 아니라 저장된 재료로 링을 **처음부터 다시 계산**하고, 다중 구역이면 거기에 '지우개'까지 덧발랐다 — 재현과 실제가 조금만 어긋나도 전부 결함이 되니 경우의 수를 하나 막으면 다른 게 튀어나오는 구조였다(v17.5~v18.3이 그 반복). 둘째로 판넬을 **벽면마다 쪼개고 이웃 평면으로 서로 잘라내는** 방식이 취약해 단독에서도 조각·각진부 마감이 깨졌다(v17.6·v17.7·v17.8·v18.2가 전부 이 한 덩어리에서 나왔다). **바꾼 것** ①**옹벽선을 정지면 만들 때 확정해 번들 v9에 저장**하고 내보내기는 **읽기만** 한다. '이어서 하기'로 뒤 구역을 만들면 **그때 앞 구역의 옹벽선을 잘라 갱신**하므로 저장된 선은 항상 최종 지표면과 일치 — 내보내기에서 지우개가 사라졌다 ②판넬은 **옹벽선을 따라 띠를 만들고 길이방향으로 균등 분할**한다. **모서리에서 띠를 먼저 끊어** 판넬이 코너를 가로지르지 않으므로 이웃 평면 절단(miter·ClipHalf·keep 부호)이 **통째로 불필요**해졌다 ③벽면이 보는 방향은 '평면에서 크레스트→토우'로 절/성토 분기 없이 한 규칙 ④모서리는 끝 열을 두께 절반(0.10m) 더 내보내 메운다(자르지 않는다) ⑤옹벽/사면 판정을 호길이가 아니라 **기하로 직접**(토우↔크레스트 간격 0.25m vs 7.5m, 30배 차이) — 전환부에서 틀리던 것 해소, 세그먼트 중점으로 재어 마이터 모서리에서 벽이 끊기던 것도 해소. **검증(S24·S25 신설)**: 프레임 비틀림 0(v18.2 오류 원천 소멸)·판넬 한 변 ≤1.667m·자투리 실오라기 0·벽선 이탈 0.03m·잘게 꺾인 벽선(현장 '벽면 62·모서리 62' 조건)에서 40패싯→벽면 1개 균등 12열·기하↔구간 판정 **불일치 0/7764점**·전체 옹벽은 단마다 한 줄(모서리에서 안 끊김)·이어서 하기 잘라내기 242m→122m 침범 0.5m·전부 덮이면 0줄·안 덮이면 무변경. 자체검증(수정을 끄면 재발) 포함. 옛 번들(v8 이하)은 종전 경로로 폴백하고 로그에 ⚠표기 — 정지면을 다시 만들면 정본 경로로 올라온다.) v18.3 (2026-08-05 — **부챗살처럼 벌어진 판넬 차단 + 원인 계측**(JACK 12:15 스샷). v18.2로 '판 만들기 실패 26장'은 0이 되고 72장 전부 저장됐지만(로그 `✔ 이상 없음`), 화면은 더 나빠졌다 — **종전에 AutoCAD가 거부해 안 보이던 판넬들이 드러나면서 부챗살처럼 벌어졌다**. 즉 그 26장은 원래부터 기하가 틀려 있었고 AutoCAD 거부가 우연히 가려주고 있었을 뿐이다(드러낸다고 옳아지지 않는다). 판넬 가로축은 '단 링 세그먼트의 3D 방향'이라 **링이 한 표고의 등고선이 아니면**(정점끼리 Z가 다르면) 판넬이 그만큼 비스듬히 선다. 조치 ①**기울기 1.15° 초과 판넬은 그리지 않고 사유별로 센다** — 종전의 조용한 삼킴을 로그로 끌어올린 상태(구멍이 남는다는 뜻이므로 자가진단 ⚠에 올림) ②**근본 원인 계측 신설** — `링Z경사 최대 Xm/Ym(링 N @ 좌표)`와 `⚠기울어진 판넬 N장 생략(최대 X° 링 N @ 좌표)`를 진단에 남겨, '왜 링이 기우는가'를 다음 로그 한 줄로 가른다 ③직교화를 `V' = W×U`로 바꿔 나눗셈·클램프 제거(비직교 프레임을 조용히 내보낼 여지 자체를 없앰). 검증(S23): 단차 부지 2890장 중 836장 생략·남은 2054장 전부 직교정규, **평면 부지는 3687장 그대로 생략 0장**(안전장치가 정상 현장을 안 건드림), 남은 판넬 월드 좌표 무변경(5.8e-11m). 검토 반영 4건: 진단 카운터를 내보내기 1회 단위로 분리(`ResetDiag` — 종전엔 Populate 2회차가 1회차의 실패 26장을 지워 '이상 없음'이 찍히는 구조였다) · 코너필러 중복 생성·오탐 차단 · 이탈검사 한계 명시(경계상자 **안쪽**에 뜬 조각은 못 잡음 — strayN=0을 '없음'으로 읽지 말 것) · nullable 경고 정리.) v18.2 (2026-08-05 — **옹벽이 사선으로 잘려 누락되던 것 — 원인 확정·수정**(JACK 스샷 2장 + 08-05 11:26 내보내기 로그). v18.0 자가진단이 한 번에 자리를 찍었다: `판 만들기 실패 26장 — 첫 사유 eCannotScaleNonUniformly`(생성 72 → 저장 46). **원인**: 판넬을 도면에 놓을 때 쓰는 좌표계가 **비틀려 있었다**. 판넬의 가로축 U는 '단 링 세그먼트의 3D 방향'이고 세로축 V는 '사면 위쪽 방향'인데, 계획선이 단차진 3D 폴리선이면(정점 높이가 다르면) 그 아래 링도 기울어 U가 수평이 아니게 되고 **U와 V가 직각이 아니게 된다**. AutoCAD의 `Solid3d.TransformBy`는 회전+이동만 받고 비틀림이 섞이면 통째로 거부하므로 그 자리 판이 아예 안 만들어졌고, `catch{}`로 삼켜져 **옹벽이 사선으로 잘려 사라졌다**(JACK 스샷의 빨간 부분 = 계획선이 단차진 구간). **수정**: V를 U에 직각으로 세우되 그만큼을 판넬 로컬 좌표에 되돌려 넣는다 — `u·U + v·V = (u+c·v)·U + (s·v)·V'` 항등식이라 **월드 좌표가 한 점도 안 움직인다**(정착구 중심도 같이 이동). 두께축 W와 앵커 방향도 불변. 검증(**S23 신설** — 오프라인 재현): 단차 계획선 2,890장 중 비틀린 판넬 **850장 → 0장**, 평면 계획선은 종전과 동일(비틀림 0). **자체검증 2중** — ①직교화를 끄면 850장이 그대로 재발 ②수정 전후 월드 좌표 최대 차이 **5.8e-11m**(=기하 무변경, 표현만 바뀜). 기존 S20·S22 결과 무변경(409·355·3353장). 함께: ①실패 사유에 **프레임 실측값**(|U|·|V|·|W|·U·V·좌표)을 붙여 다음에 또 나면 로그가 스스로 설명하게 함 ②JACK '이상한 객체가 떠있음' — 추측 대신 계측: DWG에 넣은 객체가 판넬 무리에서 5m 넘게 떨어지면 **종류·거리·좌표**를 자가진단에 표기(판넬/무늬/도넛/앵커/정착판/코너필러). ※코너 필러(quoin)는 현재 생성되는 경로가 없어 항상 0개임을 확인.) v18.1 (2026-08-05 — **사면형상(직각/라운드) 재시작 보존 + 기본값 통일**: ①사면형상이 정적 설정이라 Civil3D를 껐다 켜면 무조건 '직각'으로 돌아가, 라운드로 쓰던 사용자는 아무것도 안 바꿔도 결과가 확 바뀌었다(v17.6 '같은 부지·같은 설정인데 옹벽 6장↔163장'의 뿌리 — 사용자 과실 아님). 정지옵션 [저장] 시 사면형상을 레지스트리(HKCU\\Software\\DHGrading)에 기록하고 애드인 시작 때 복원 — 마지막으로 저장한 값이 다음 세션 기본값이 된다. 정지면 기록(번들) 있는 도면은 종전대로 도면 값이 우선(SyncToDocument — 도면이 정본). ②GradingParams.MiterConvex 기본값이 false(라운드)로 GradingSettings 기본값 true(직각)와 반대였던 지뢰 제거 — 실사용 경로는 전부 명시 대입이라 동작 무변경이나, 명시 대입을 빠뜨린 코드가 조용히 라운드로 만들 자리였다(blocktest 전 케이스 명시 대입 확인). ③INFRAWORKS 내보내기 로그의 앵커판넬 줄 맨 앞에 '사면형상 직각|라운드' 표기 — 옹벽 수 차이 신고 시 '벽면=모서리면 직각' 추론 없이 이 한 단어부터 본다.) v18.0 (2026-08-05 — **'이어서 하기' 옹벽 — 허공의 앵커봉·거대 쐐기 판넬 + 로그만 보고 판정하는 자가진단**(JACK: 사면 생성 → 옹벽 변환 → 2단부터 사면 → 인접 계획 2개소 정지. 뒤 구역이 1구역 옹벽을 덮어 일부 사라지는 건 정상이나 그 경계에서 쓰레기 기하 발생). ①**허공의 앵커봉** — 판 만들기(압출)가 실패해도 `catch{}`로 조용히 삼킨 뒤 앵커·정착판·도넛을 **그대로** 만들어, 판넬 없는 자리에 앵커봉만 남았다(현장: 생성 72장 → DWG 46장인데 앵커 45개 — 이 불일치가 로그 어디에도 없었음). 판이 실패하면 그 패널 부속 전부 생략 + 실패 수·첫 사유 로그. ②**거대 쐐기 판넬** — 판넬 한 변은 '단 높이'로 정하는데(≤1m→높이, ≤3m→½, ≤5m→⅓) 그 단 높이를 이웃 두 링의 **평균 Z 차이**로 잰다. '2단부터 사면'처럼 구간마다 옹벽/사면이 섞이면 사면 쪽이 확 퍼져 평균이 크게 튀고, 한 변 10~20m짜리 판넬이 나왔다(JACK 스샷). 한 변을 설계 상한(1.67m) 이하로 분할(여유 0.5m — step은 평균이라 5m 단이 5.0002m로 나온다. 여유 없이 걸면 정상 부지마다 거짓 경보가 뜨고 판넬 크기까지 바뀐다: 실측 409→412장). ③**자가진단 블록 신설**(JACK '돌리고 내보내기만 해도 오류 판단 가능하게') — 내보내기 로그 끝에 `■ 옹벽 자가진단` = 생성→저장 대사, 앵커>판넬 검사, ⚠항목 모음, 이상 없으면 `✔ 이상 없음`. 패널 진단에 `판넬한변 최대`·`⚠이상판넬 N장(최대폭·좌표)`·`패널범위 / 링범위 — 범위 정상|⚠링 밖 N m 이탈` 추가 — 스샷 없이 로그만으로 이상과 그 위치가 갈린다. ※`ClipHalf` 좌표 폭주 의심은 배제(보간 계수가 0~1로 묶여 불가능). v17.9 (2026-08-05 —**성토 안의 알 수 없는 초록선 — 여유값이 커서 못 걸러내던 것**: v17.7의 '정지 구역 안에 갇힌 교선 고리 표시 제외'가 실제로는 0개를 걸렀다. 진단 로그로 확인한 실측값 — 진짜 경계선은 클립링과 겹쳐 **0.0m 안쪽**으로 찍히는데 문제의 고리(191점)는 **0.8m 안쪽**에 떠 있었고, 여유를 1.0m로 잡아 아슬아슬하게 빠져나갔다. 두 값이 깨끗이 갈리므로 여유를 **0.3m**로 좁힘(현장 실측값 0.8m를 S21 검사에 그대로 넣어 회귀 고정). 진단 로그도 고리마다 '점수·길이·닫힘/열림·판정·경계와의 거리'를 남겨, 다음에 또 남으면 그 줄만 보고 갈린다. v17.8 (2026-08-05 —**코너 옹벽 누락 — 자를 방향(keep 부호)이 뒤집히던 것**: v17.7 이후에도 남은 코너 누락(JACK 위에서 본 스샷 — '코너에 판넬이 크로스되고 그 뒤로 누락되다가 다시 생김'). 코너 마감은 '패널을 이웃 벽면 평면으로 잘라내기'인데, **어느 쪽을 남길지 정하는 기준점**을 첫 세그먼트의 직선을 face 한가운데 호길이까지 연장한 점 **하나로** 잡아 양쪽 끝을 다 판단했다. 한 벽면이 여러 세그먼트에 걸치면(사면형상 라운드면 항상 — 원호 꺾임이 25° 미만이라 벽면이 안 갈림) 그 점이 실제 벽에서 크게 벗어나 부호가 뒤집힌다 → 남길 쪽과 자를 쪽이 바뀌어 코너를 가로지르는 조각만 살고 정작 코너 패널이 잘려나갔다. 수정: 기준점을 **양 끝단 각각의 실제 벽면 위 점**(시작=첫 세그먼트에서 조금 안쪽 / 끝=마지막 세그먼트에서 조금 안쪽)으로 분리. 검증(S22 — 현장 경계 11점 그대로·라운드): 코너버림 **38~55 → 0**, 옹벽 3315→3353장. ※'크로스' 증상 자체는 오프라인에서 재현되지 않아 확정 못 함 — JACK 실기 확인 필요. 함께: **진단 로그의 '줄눈' 손실 정체 규명** — 각 단의 마지막 행은 사면길이가 단높이로 딱 안 나눠져 수 mm짜리 실오라기가 되는데(slopeLen=step/vUp), 줄눈 인셋이 그걸 전부 지워 '줄눈 366'처럼 큰 손실로 보였다. 실제로는 정상이라 미리 걸러 '실오라기[단 나머지—정상]'로 따로 센다(재현: 줄눈 1690→5·패널 수 무변경) — 앞으로 로그의 '줄눈'은 진짜 손실만 뜻한다. v17.7 (2026-08-05 —**코너 옹벽 누락 + 엉뚱한 곳의 옹벽 조각 = 같은 버그 하나, 그리고 성토 안의 초록선**. ①[치명] 벽면 목록의 **마지막 하나는 링 시작점을 지나 감기는데**(호길이가 둘레를 넘음) 좌표를 계산하는 `Walk.AtSeg`가 호길이를 되감지 않아, 그 자리 패널이 접선 방향으로 **둘레 길이만큼(현장 실측 부지 밖 137m)** 날아갔다. 세그먼트를 고르는 `SegOf`는 되감는데 좌표를 내는 쪽만 안 되감던 불일치. 결과가 지형에 따라 두 얼굴로 갈려 따로따로 보였다 — 날아간 패널이 데이라잇 밖이면 **코너가 그냥 비고**, 살아남으면 **수백 m 밖에 조각으로 나타난다**. 되감기 추가로 둘 다 해소(재현 테스트: 옹벽 253→333장, 감긴 벽면 몫 80장 회복). 코너 미터의 의도된 연장(수십 cm~수 m)은 둘레 절반에 한참 못 미쳐 그대로 보존. ②**성토 구간 안의 알 수 없는 초록선**(JACK 스샷) — 정지경계 표시가 걸러진 교선 고리를 **전부** 그려서, 경계로 쓰이지도 않는 안쪽 고리(정지 구역 안 둔덕과 원지반이 만나는 자리)가 경계처럼 보였다. 그 둔덕은 어차피 깎여 계획면이 되므로 최종 지형엔 그 경계선이 없다(JACK 지적) → **실제 주입된 클립 경계 안쪽에 완전히 갇힌 고리는 표시 제외**(바깥 경계선은 클립링과 겹쳐 있어 보존, 여유 1m. 클립링이 없으면 아무것도 안 지움). 표시 전용 — 기하·토량·SHP 무관. ③검증: 하네스 S20(사면형상별 옹벽·포개짐·링 밖 이탈 + **되감기를 끄면 실제로 나빠지는지 자체검증**)·S21(초록선 필터) 신설. 진단 로그에 '벽면 N(짧은면 M) · 모서리 K · 패널범위 X[..] Y[..]' 추가 — 이 두 숫자가 이번 원인을 갈랐다. v17.6 (2026-08-05 —**절토 옹벽(앵커판넬) 누락 수정 — 사면형상 '라운드'에서 벽이 통째로 사라지던 문제**: JACK 신고 '같은 부지·같은 설정인데 어떤 날은 옹벽이 6장, 어떤 날은 163장'. 원인은 정지옵션의 **사면형상(직각/라운드)**이었다(Civil3D를 껐다 켜면 설정이 초기화돼 사용자가 손대지 않아도 모드가 바뀜). 라운드는 볼록 모서리를 원호로 만드는데, 원호 조각의 꺾임이 25° 미만이라 벽면 분할선이 안 잡히고 **한 벽면이 원호 전체를 덮는다**(실측: 모서리 350→27개·벽면 350→63개). 그런데 코너 마감(미터)은 '패널을 이웃 벽면의 평면으로 잘라내기'인데 이걸 그 휘어진 면 **전 구간에** 걸고 있어서, 원호 중간 패널들이 이웃 평면 바깥으로 밀려 통째로 잘려나갔다(행 364개 중 208개 소실 → 옹벽 408→90장). 수정: 미터 절단을 **모서리 근처 스팬에만** 적용(곧은 면에선 중간 스팬이 어차피 절단에 안 걸리므로 직각 모드 결과는 한 장도 안 변함 — 408장 동일 검증). 결과 라운드 90→253장·코너 소실 208→24. 실제 현장 경계(0804 로그 7점)로 오프라인 재현 테스트 S20 신설 — 링 점수까지 실제 로그와 일치(직각 87점/라운드 116점 vs 현장 87/117). 진단 로그에 '벽면 N(짧은면 M) · 모서리 K' 추가 — 옹벽 누락 신고 시 이 값부터 본다. v17.5 (2026-08-04 —**'이어서 하기' 옹벽 3D·SHP 띠 잔재 수정**(JACK 스샷 — 성토면 속 잘린 절토 조각·사면 위에 뜬 앵커판넬): 뒤 구역이 덮은 자리를 빼는 발자국 마스크가 자기접촉(핀치) 교선 링을 정리할 때 '최대 조각 하나'만 남기고 나머지 로브를 통째로 버려 — 그 빠진 자리에 앞 구역의 패널·절토 띠가 살아남았음(경계 주입 IllegalBoundary가 핀치의 증거. 노리선만 멀쩡했던 이유: 노리선 클립은 조각 전부 유지하는 별도 경로). 수정 4중: ①핀치 링 분해 조각 **전부 유지**(ToCleanGeometry) — 옹벽3D 마스크·띠 SHP 구멍·계획면 차감·띠 도넛·옹벽면 쐐기 다섯 경로 전환 ②앵커판넬 keep 판정을 스팬 중점 1점→양끝+중점 **3점 다수결**(발자국 경계에 걸친 패널이 통째로 살아남던 것) ③번들 v8 — 표면에 **실제 주입된 클립경계**(교선∪계획, 정규화 반영)를 저장해 발자국 마스크의 정본으로 사용(순수교선과의 미세 불일치 제거 — v7 이하 옛 번들은 순수교선+계획 폴백) ④진단 로그 강화 — 변환 구간을 '옹벽/구배변경'으로 갈라 세고 구간별 규칙(몇 단부터 1:n·소단폭)을 그대로 덤프 + 마스크 조각 수 표기('[구역2] 옹벽 구간 반영인데 쐐기·패널 0'이 옹벽 규칙 부재인지 마스크 탓인지 다음 로그에서 바로 판별). 기존 도면도 재작업 불필요 — 마스크 다조각은 옛 번들에 즉시 적용되고, 클립링 정본은 새로 만드는 구역부터 쌓인다. v17.4 (2026-08-04 — **INFRAWORKS 내보내기 — 다중 구역 정합 마무리**: '이어서 하기'로 구역을 쌓은 도면에서 내보내기가 최종 지표면과 안 맞던 나머지 구멍들. ①**계획면.shp** — 뒤 구역 사면이 앞 구역 계획면을 침범한 만큼 뺀다(침범 부분은 최종 지표면에서 더 이상 계획고 평면이 아님 — 종전엔 원래 계획폴리곤 전체가 그대로 나감, JACK 스샷). 침범으로 조각나면 조각별 피처, 로그에 '[구역N] 계획면: 뒤 구역 침범 X㎡ 제외' ②**역T 옹벽 런** — 뒤 구역이 덮은 자리의 구간을 걷어내고 연속 구간별로 분할(종전 마스크가 패널·블록·띠에만 걸려 있었음) ③**앵커판넬 코너 필러(quoin)** — keep 필터를 안 타므로 뒤 구역 마스크 별도 적용. v17.0의 발자국 제외가 이제 내보내기 전 항목(띠·패널·블록·역T·필러·계획면)에 일관 적용. v17.3 (2026-08-04 — **'⚠ 확인 필요' 팝업 오탐 수정**: 전부 절토(또는 전부 성토)인 부지에서 반대 방향 교선이 전부 5㎡ 미만 짜투리로 걸러지면 — 예: 계획고보다 낮은 곳이 4.5㎡ 웅덩이뿐 — 이를 '링 생성 실패'로 오분류해 정지면이 정상 완성됐는데도 매번 '⚠ 정지면 생성 — 확인 필요 / 토량 산출 안 함' 팝업이 뜨던 문제. 이제 '그 방향 유효 사면 없음'으로 처리 — 정상 완료 팝업 + 토량 계산 진행. 진단 로그의 maxΔZ 표기에 'ΔZ>2m 교차는 스냅 생략(안전판)' 주석 추가(v17.2 안전판 이후 이 값은 진단용일 뿐 형상 무해). v17.2 (2026-08-04 — **뾰족 지표면(침봉 스파이크) 수정**: 단차 계획선(3D폴리선, 일부 구간 고도 다름) + 옹벽/사면 구간 조합에서 사면 변환 후 지표면에 40m급 침봉이 서던 문제(진단 maxΔZ 41.032m). 원인: 단차경계선이 링과의 교점을 '전역 사면 거리와 비슷한 t'로 골라(|t−dist|) — 옹벽 구간의 실제 링은 경계 1~13m 안에 붙어 있는데 70m 밖 엉뚱한 사면 조각에 교점이 꽂힘 → 그 선이 옹벽 링들을 가로지르고, 교차점 공유정점 삽입이 그 지점 Z를 링 값(160.5)으로 강제해 41m 수직 절벽 생성. 수정 3중: ①교점 = 가장 가까운 교점(min t, 링별 단조 증가) — 구간이 있든 없든 그 방향의 실제 표면 ②코너 능선 추적의 링당 이동 상한을 그 코너 위치의 구간 프로파일 간격으로(전역 거리 기준 21m 허용이 옹벽 구간 1.25m 간격에서 이음매 꺾임에 낚이던 것) ③안전판 — Z가 2m 넘게 어긋난 교차점은 공유정점 스냅을 건너뜀(절벽 제조 차단, Civil3D 교차 경고는 무해). 검증: 스샷 시나리오(단차+옹벽구간) 재현 테스트에서 교차 Z간극 41m→0.00m, 구간 없는 단차 부지 회귀 없음. v17.1 (2026-08-04 — **스샷 버그 수정: 일부 구간만 변환했는데 그 단 전체가 바뀌던 문제**. 원인: 겹치는 두 구간(기존 옹벽 + 새 선택)을 '합집합 하나'로 뭉개고 규칙을 합쳐서, 새 규칙이 노란선 범위가 아니라 옹벽 구간 전체에 퍼짐. 수정: 겹침을 교집합/차집합 **조각으로 갈라** 각 조각에 해당 규칙만 남김(SlopeZone.Flatten — 조각별 합성은 시간 순서로, 나중 클릭은 자기 단부터 바깥의 기존 규칙을 대체 = '클릭한 단부터 바깥 끝까지' 의미 그대로. 랩 구간 포함 검증). 함께: 변환 명령 멘트 간결화 — '절토 소단 길이' → '소단 길이', 안내 한 줄, 질문은 '사면 경사 1:n'·'소단 길이 (m)'만(JACK). v17.0 (2026-08-04 — **변환 방식 개편 + 다중 구역 겹침 수정**. ①[옹벽 변환]·[사면 변환]이 **1회 1개**만 바꾼다: 선을 연달아 눌러도 마지막에 누른 것만 선택되고, Enter(스페이스)를 치면 제원을 묻는다 — 옹벽=소단 길이 / 사면=사면 경사·소단 길이. 입력값은 클릭한 단부터 바깥 끝까지 적용되고, 여러 번 실행하면 규칙이 쌓여 아래/위를 다르게 줄 수 있다. 두 명령이 같은 코드를 쓰고 묻는 항목만 다르다. ②단높이는 묻지 않는다(JACK B안) — 링은 '같은 표고의 등고선'이라 링 하나에 표고가 하나뿐이고, 구간마다 단높이가 다르면 같은 링에서 구간 안/밖 표고가 달라져야 해서 표현이 안 된다. 묻기만 하고 안 먹으면 오해를 부르므로 아예 뺐다(단높이는 정지옵션에서 방향별로). 구배·소단폭은 표고 순서를 바꾸지 않아 구간별로 정상 동작. ③**'이어서 하기'로 구역을 쌓았을 때 노리선·INFRAWORKS가 최종 지표면이 아니라 구역들이 겹쳐 나오던 문제 수정**: 뒤 구역이 앞 구역 사면을 덮어썼는데도 앞 구역 번들의 옛 경계로 그리고 있었다 → 구역마다 '뒤 구역들의 발자국'을 빼고 그리도록(노리선·사면선/소단선·SHP 띠·옹벽 3D 네 곳 전부). v16.9 (2026-08-04 — **구간별 구배 변경**: [사면 변환](DHSLOPE)에서 계단선을 클릭하면 그 단부터 바깥의 구배를 원하는 값으로 바꾼다. 옹벽선뿐 아니라 **사면선도 클릭 대상**이라 이미 사면인 곳의 구배만 완만하게/급하게 조정할 수 있다. 명령 중 [구배] 로 적용할 값을 바꿔가며 여러 단을 찍으면 규칙이 쌓여 **아래는 급하게·위는 완만하게**가 된다(예: 1단부터 1:1.0 + 3단부터 1:2.0 → 1~2단 급경사, 3단~ 완경사). 구조 개편: 구간이 '이 단부터 이 구배' **규칙 목록**을 갖게 되어 옹벽(1:0.05)·사면 되돌리기(원래 구배)·구배 변경이 전부 같은 한 가지로 통일됨 — 옛 끝단(ToBench)은 '그 다음 단부터 원래 구배' 규칙으로 무손실 표현. 번들 v7(옛 v6~v3 도면은 SlopeZone.Wall로 정확히 같은 의미로 변환해 계속 읽음). 노리선·사면선·옹벽3D·SHP는 구간 안이라도 그 단 구배가 수직이 아니면 사면으로 처리. 기하 검증: 전역보다 완만한 구간이 바깥으로 퍼지는 경우(종전엔 안쪽으로 당겨지는 경우만 검증됨)를 신규 테스트로 확인 — 링 단조 증가·자기교차 없음. v16.8 (2026-08-03 — **설정이 도면을 따라다니게**: 정지옵션 값과 '마지막 작업 기억'이 Civil3D 전체에 한 벌뿐이라 도면을 바꾸거나 재시작하면 그 도면 것으로 돌아오지 않던 문제를 수정. 이제 명령을 실행할 때 도면이 바뀐 것을 감지하면 ①그 도면에 저장된 정지 파라미터(구배·단높이·소단폭·격자·대소단 등)를 설정으로 복원 ②다른 도면의 계획선·원지반 위치 기억과 옹벽 선택 목록을 폐기(그 핸들은 이 도면에서 엉뚱한 객체를 가리킬 수 있음 — 번호가 도면마다 순서대로 붙어 겹치기 쉬움) ③도면 좌표계가 지정돼 있으면 그 값을 따름. 증상이던 것: 다른 도면을 열고 [옹벽 변환]을 누르면 '이전 구역의 선'이라며 아무것도 못 고르거나, Civil3D 재시작 후 옹벽 하나 찍었을 뿐인데 정지면 전체가 기본값(구배 1:1.5·단높이 5m)으로 다시 만들어져 모양이 바뀜. 정지면 기록이 없는 새 도면은 직전 값을 그대로 둠(비슷한 현장 연속 작업 편의). 같은 도면 안에서는 아무것도 하지 않으므로 방금 바꾼 정지옵션 값은 보존. v16.7 (2026-08-03 — **전체 옹벽에서 부분 사면 복귀**: 정지옵션 구배 0으로 처음부터 전체가 옹벽으로 나온 경우에도 [사면 변환](DHSLOPE)으로 원하는 구간·단부터 사면으로 되돌릴 수 있다. 방식: 그 방향의 둘레 전체를 합성 구간으로 잡아 모든 계단선을 클릭 대상으로 만들고, 적용 때 '전역 구배=입력한 사면 n + 옹벽 구간=선택 구간의 여집합'이라는 **등가 표현**으로 바꿔 재생성(전체옹벽인데 일부만 사면 ≡ 전체사면인데 나머지가 전부 옹벽). 등가성은 기하 테스트로 검증(면적차 0.000㎡·표고차 0) — 기하/노리선/옹벽3D/SHP 무변경. 적용 후 상태는 일반 '사면+옹벽구간' 표현이 되므로 이후 옹벽변환·사면변환이 평소대로 동작. 함께 수정: 정지옵션 구배가 이미 수직인 방향은 [옹벽 변환]에서 선택 대상 제외(종전엔 찍혀도 형상·3D가 안 바뀌는데 '옹벽 추가' 성공 메시지가 나와 헛클릭인 줄 알 수 없었음) — 사면 변환으로 안내. 검토 반영 7건: ①**재생성 시 그 구역의 저장된 파라미터를 먼저 복원**(GradingSettings.RestoreFrom) — 재생성은 세션 설정을 읽는데 Civil3D 재시작 후엔 기본값이라, 손대지 않은 방향의 옹벽이 통째로 사면이 되어 사라졌음(단높이·소단폭·격자도 동일) ②부지를 한 바퀴 도는 '닫힌 고리' 선은 구간을 둘레 전체로 명시 — 종전엔 정점 간극이 여집합에 남아 사면 한가운데 폭 1~13m 가짜 수직 옹벽이 섰고, 구간 지정도 무의미했음(클릭 시 안내 표시) ③구간 병합이 양끝에서 서로 물릴 때 합집합을 둘레 전체로(종전 공식은 결과가 줄어 사면 선택분이 옹벽으로 남았음) ④구배 입력을 선이 화면에 보이는 상태에서 두 방향 먼저 받고 재생성 직전 한 번만 대입(중간 실패 시 정지옵션 오염 방지) ⑤호길이 구간을 못 구한 선은 클릭 시점에 거부(종전엔 '선택' 메시지만 나오고 조용히 버려짐) ⑥옹벽 변환의 '대상 없음' 차단을 실제 수직 제외가 있을 때만(다중 구역에서 반대 방향 작업까지 막히던 것) ⑦수직 판정 기준을 두 명령이 공유(안내 문구 모순 제거). v16.6 (2026-08-03 — **단높이·소단폭 절성토 분리**: 정지옵션이 '절토 단높이/절토 소단폭/절토구배 · 성토 단높이/성토 소단폭/성토구배' 6칸으로 분리(대소단 간격·폭은 공용 유지). 예시 그림도 각 쪽 값으로 그림. 안전장치 5건: ①번들 v6 — params가 14→17필드가 되어 옛 도면(v5·v4·v3)은 14필드 리더로 갈라 읽음(안 그러면 뒤 필드가 통째로 밀려 조용히 엉뚱한 값이 됨). 기존 도면의 옹벽변환·INFRAWORKS 그대로 작동 ②사면의 수직 예산(MaxRise)을 단 개수 상한(MaxBenches)에서 분리 — 둘을 곱해 예산을 만들면 단높이가 작은 쪽이 개수 상한(50)에 걸리는 순간 반대쪽 예산까지 주저앉아 사면이 원지반에 닿기 전에 끊김(표고차 > 48×작은단높이에서 발동). 예산은 이제 단높이와 무관한 실제 표고차에서 산출 ③역T형 '1단 이내' 판정에 그 방향의 단높이 사용 ④단높이 하한 0.2m 검증 추가(예시 그림 클램프와 동일 — 없으면 0.01이 경고 없이 저장돼 화면과 실제가 어긋남) ⑤원지반 표고범위 산출 실패를 조용히 삼키지 않고 진단 로그 기록. v16.5 (2026-07-31 — **종단·횡단 신설**: [종단/횡단] 버튼(DHSECTION) — 노선으로 쓸 선을 클릭하면 Civil3D 정식 객체(선형·종단·종단도·측점선·횡단도)로 원지반·정지면 종단면도와 횡단면도를 생성. 사용자가 그린 선은 보존(평면 사본으로 선형 생성), 3D폴리선·2D폴리선·선분 모두 지원. 횡단 간격·좌우 폭·가로 배치 수는 정지옵션에 추가(기본 20m·좌30·우30·3개), 횡단 상한 200개. 초기화(DHRESET)가 선형·종단·종단도·측점선그룹·횡단도까지 순서대로 정리. v16.4: ①배경지도 위로 지번 글자가 보이게 그리기 순서 정리(사진=맨 아래·지번=맨 위. 원인: 트루타입 글자는 이미지와 같은 '채움' 단계라 순서에 밀림 — 선은 원래 위에 그려짐) ②서버지표면 생성 시 스타일을 삼각망 대신 등고선(주 25m·보조 5m, 경계 표시 유지)으로 자동 지정. v16.3: 가져오기: 지적도·등고선을 지정한 사각 범위대로 정확히 클립(도면 좌표계 기준 자르기, 인덱스는 DB좌표계 박스로 선필터)·지번 글자 크기 1.0 고정. v16.2: 지적 팝업 문구 정리(GIS_Design_Loader server 제공)·좌표계 변경 팝업 간결화·서버지표면 보충점 3m/중간종거 0.05(등고선 위 점이라 표고 정확). v16.1: 가져오기 개선: ①지표면 정밀도(단순화 끔·weeding 최소·supplementing 5m·평탄부 최소화 전부 켬) ②지번 한글 깨짐 수정(트루타입 '맑은 고딕' 스타일) ③지적 선 노란색 ④버튼명 '서버지표면'·가져오기 패널을 내보내기 앞으로. v16.0: 가져오기 신설: [지적도] 범위 내 필지+지번(별도 레이어), [등고선] 수치지형도 등고선 3D + '원지반' 지표면 자동 생성. 사내 PostGIS 직결(도면 좌표계로 변환해 수신). 좌표계 변경 시 가져온 자료가 있으면 예/아니오 확인 후 전부 초기화(아니오=변경 취소). 리본 재편: 가져오기/부지정지/도면화(배경지도·지도끄기 이동)/내보내기/기타. v15.9: '이미지를 분리할까요?' 창 근본 해결: 원인=Raster Design 사용자 설정(이미지 분리 방식=물어보기). 시작 시 '항상 분리(ImageDetachMode=1)'로 자동 설정(레지스트리, 배포 PC 포함) — 코드 우회가 아니라 설정 차원 차단. v15.8: 좌표계 변경 시 새 위성자료를 못 받는 배경지도는 그대로 두지 않고 삭제(위치 틀린 지도 방치 방지·안내 팝업). v15.7: '이미지를 분리할까요?' 창 재수정: ①좌표계 변경은 삭제 대신 **제자리 교체**(정의 파일·배치만 갱신 — 삭제가 없으니 창도 없음) ②지도끄기는 도면 전체 참조 스캔으로 정의를 확실히 먼저 삭제. v15.6: 배경지도 삭제/좌표계 변경 시 Raster Design '이미지를 분리할까요?' 창 제거: 이미지보다 정의(RasterImageDef)를 먼저 삭제해 통지 자체가 안 나게(참조가 전부 우리 것일 때만). 회귀 수정: ①'결과지표면만 표시' 즉시 반영이 v15.4 조기 return에 막혔던 것 복구 ②구좌표/UTM-K 선택이 정지옵션 재진입 때마다 신좌표로 리셋되던 것 수정. v15.4: 좌표계 안전장치(치명 수정): ①정지옵션 콤보를 도면 좌표계로 초기화 ②좌표계를 실제로 바꿨을 때만 도면 좌표계 변경·배경지도 갱신(안 바꾸면 무변경) ③배경지도 갱신은 선다운로드 후교체(실패 시 기존 유지+안내) ④구좌표/UTM-K는 정지옵션 값 우선 ⑤삭제 반응자 가드를 커밋까지 확장. v15.3: 정지옵션 좌표계 저장 시: ①도면 좌표계도 함께 변경(MAPCSASSIGN 상당) ②이미 깔린 배경지도를 새 좌표계로 자동 재생성. v15.2: 배경지도 수정: ①배치 정확도(캐시 해상도 역산·좌상단 기준 오차 제거 — GeoTIFF 태그 직접 읽기) ②UCS 회전 도면 대응 ③지도끄기 시 Raster Design '분리할까요?' 창 안 뜨게(반응자 전역 토글) ④다운로드 진행막대 ⑤정지옵션 좌표계 저장 시 도면 좌표계도 함께 변경(MAPCSASSIGN 상당). v15.1: 위성 배경지도: [배경지도] 두 점 범위 클릭 → 브이월드 위성을 도면 좌표계(정지옵션 좌표계)로 재투영해 부착(맨 아래 배치·같은 범위 재사용), [지도끄기] 한 번에 전부 제거. 화질은 정지옵션에서 선택(높음/보통/낮음, 범위 넓으면 자동 하향). v15.0: 정지면 생성 중 이벤트 뷰어 알림(팝업)만 끄기: 앰비언트 ShowEventViewer를 실행 동안 false 후 원복(기록은 남음 — EVENTVIEWER로 수동 확인 가능). v14.9: 역T 끝단 마감: 30cm 뭉툭 절단 → 데이라잇 교차점까지 테이퍼 수렴(트림 2cm+경계 한 칸 확장), 무늬 클립 중복정점 정리 보험. v14.8: 역T ①상단 계단→지형 추종 연속 경사(전면 다각형을 두께로 압출, 정점 높이 공유·무늬는 경사선 클립) ②대좌표 ACIS 간헐 실패(구멍 2곳) — 원점 생성 후 이동으로 수정. v14.7: 역T 무늬 eInvalidInput 전수 실패 수정: union 후 일괄 압출 → 돌 개별 압출·개별 배치(벽체 세그와 동일 경로), 실패 세그 상세 로그(위치·치수·사유). v14.6: ①뷰포트 2분할 기능 제거(옹벽/사면 변환 — -VPORTS 네이티브 크래시, JACK 지시) ②역T/앵커판넬 무늬 소실 원인 후보 수정: 저장 전 솔리드 검증을 '확실한 증거 있을 때만 제외'로 완화(다중 덩어리 무늬 솔리드 오폐기 방지) ③역T 생성 상세 진단 로그(세그·스킵·브리지·무늬·깨진솔리드 수 — DHINFRA 로그 표기). v14.5: 옹벽/사면 변환 클릭 스냅(근본 해결): 클릭이 계획폴리곤·등고선 등 겹친 다른 객체에 먹혀도 클릭 지점 주변을 우리 레이어 3D 폴리선 필터로 재검색해 우리 선으로 스냅(SnapToLayerLine). v14.4: 역T 4종 수정: ①양끝 데이라잇 트림(스텁 제거) ②중간 낮은 구간 브리지(누락 금지) ③전체 1cm 하강+전면 5cm 돌출(지표면 z-fighting 방지) ④전면 노출면 자연석 무늬. v14.3: 옹벽/사면 변환 선택 시 3D 폴리선만 집히게: 선택 순환 팝업 명령 중 끄기+우리 선 그리기 순서 맨 위(PickGuard)+기존 클래스 필터 3중 방어. v14.2: 뷰포트 2분할 시 3D 쪽도 와이어프레임(둘 다 와이어프레임, 음영 제거)). v14.1: ①옹벽/사면 변환 시 화면 좌우 2분할(왼쪽 평면·오른쪽 3D)로 선택, 끝나면 단일 평면 복원 ②초기화 버튼 초록 리셋 아이콘·'기타' 중분류로 이동. v14.0: ①INFRAWORKS 내보내기 저장오류(모델링 오류 115094·RECOVER 모달) 수정: 옹벽3D.dwg 저장 직전 깨진 ACIS 솔리드 검사·제거 + 무늬 압출 퇴화 다각형 사전 정리 ②초기화 버튼(DHRESET): 정지면 생성 전(원지반+계획폴리곤)으로 복원 ③3D 뷰 전환 LISP(v1~v4·vv1~vv3) 애드인 자동 로드 내장. v13.9: ①작업공간 전환 시 'DH 정지' 리본 탭 사라짐 수정(WSCURRENT 감지 후 재생성) ②도넛 돌출부 데이라잇 클립: 도넛(0.56m)이 데이라잇·코너 절단선에 걸치는 판넬은 앵커 생략(온전 판정 반경 0.1→0.30, 네 모서리 검사). v13.8: 앵커판넬 정착구 도넛 돌출(패널옹벽예시.png): 1단 0.56m×5cm+2단 0.36m×10cm 계단식, 2단 전면 홈·정착판, 무늬 제외역 확장. v13.7: 발 단면 철회(균일 20cm+무늬). v13.4: 역T 안내문구·앵커판넬식 명칭 정리. v13.3: ①역T형=1단 옹벽 전용(선택 시 팝업 안내, 2단 이상 구간은 절토=앵커판넬·성토=보강토 자동 대체, 지반고 기반 순수 1단 판정) ②콘크리트 스타일 삭제, 자연석 무늬를 앵커판넬로 이식(정착구 주변 제외). v13.1: FGL 심볼 수정: 11시 사분면 호 방향(반시계 통일)·해치 고도=심볼 고도. v13.0: ①옹벽변환 대상=옹벽이 시작되는 선만(절토=소단선·성토=사면선, 중복 표현 제거) ②사면변환 같은 구간 재클릭=교체(구간당 1개). v12.9: 사면 변환 개선: ①같은 단 조각들 한 건으로 묶음 선택 ②절토 클릭 대상=각 옹벽 아랫선(클릭한 옹벽부터 사면, 성토와 규칙 통일). v12.8: 버튼 개명 옹벽·사면 변환+툴팁 개념도 이미지. v12.7: 옹벽생성 재사용 시 기존 옹벽 유지: 새 선택과 병합(겹치면 교체·안 겹치면 추가), '전체해제'만 전부 초기화. v12.6: 사면 생성(DHSLOPE)·FGL 플래토별)";

